-- The career catalogue: every career the quiz can match, the explorer lists
-- and a roadmap can belong to. Moved here from careerAI's
-- scripts/riasec_careers.js (see that file's header for what each field
-- means); the frontend loads it from GET /careers.

CREATE TABLE IF NOT EXISTS careers (
  title      text        PRIMARY KEY CHECK (length(title) BETWEEN 1 AND 80),
  emoji      text        NOT NULL,
  field      text        NOT NULL,
  -- Careers that would compete for the same shortlist slot share a family.
  family     text        NOT NULL,
  stream     text        NOT NULL,
  salary     text        NOT NULL,
  -- 0-100 per dimension, e.g. {"R":35,"I":90,"A":40,"S":30,"E":35,"C":75}.
  riasec     jsonb       NOT NULL CHECK (jsonb_typeof(riasec) = 'object'),
  -- Where the work happens, main one first (RS_DOMAINS in riasec_engine.js).
  domains    jsonb       NOT NULL CHECK (jsonb_typeof(domains) = 'array'),
  subjects   jsonb       NOT NULL CHECK (jsonb_typeof(subjects) = 'array'),
  why        text        NOT NULL,
  -- Catalogue order; the matching engine sees careers in this order.
  sort_order integer     NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

ON CONFLICT (title) DO NOTHING;

-- A roadmap must belong to a career in the catalogue; renaming a career
-- carries its roadmap along.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'career_roadmaps_career_fkey') THEN
    ALTER TABLE career_roadmaps
      ADD CONSTRAINT career_roadmaps_career_fkey
      FOREIGN KEY (career) REFERENCES careers (title) ON UPDATE CASCADE;
  END IF;
END $$;
